import{_ as o,C as s,c as n,o as i,j as t,G as l,ag as d,a}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/lsm-image.webp",S=JSON.parse('{"title":"Zeiss LSM Viewer","description":"Free online Zeiss LSM viewer: open .lsm files from LSM 510, 710, 780 and 880 confocals in your browser, with every channel, Z-stack and time series. From your disk or a link. Nothing to install.","frontmatter":{"title":"Zeiss LSM Viewer","description":"Free online Zeiss LSM viewer: open .lsm files from LSM 510, 710, 780 and 880 confocals in your browser, with every channel, Z-stack and time series. From your disk or a link. Nothing to install."},"headers":[],"relativePath":"guides/zeiss-lsm.md","filePath":"guides/zeiss-lsm.md"}'),c={name:"guides/zeiss-lsm.md"};function p(f,e,m,u,g,b){const r=s("OpenViewer");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"zeiss-lsm-viewer",tabindex:"-1"},[a("Zeiss LSM Viewer "),t("a",{class:"header-anchor",href:"#zeiss-lsm-viewer","aria-label":'Permalink to "Zeiss LSM Viewer"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Open "),t("code",null,".lsm"),a(" files from Zeiss LSM 510, 710, 780 and 880 confocals, saved by ZEN or AIM. You get every channel, Z-stack and time series. LSM files shared on Zenodo open by their link.")],-1)),l(r,{format:"LSM",example:"https://find-nuclei.github.io/examples/formats/10-01.lsm",label:"a four-channel confocal LSM"}),e[2]||(e[2]=d('<p><img src="'+h+'" alt="10-01.lsm open in the viewer: a four-channel confocal section, with each channel named and coloured as ZEN saved it"></p><h2 id="how-to-open-an-lsm-file" tabindex="-1">How to Open an LSM File <a class="header-anchor" href="#how-to-open-an-lsm-file" aria-label="Permalink to &quot;How to Open an LSM File&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Working with many files?</p><p>Chrome and Edge on a computer open a whole folder as a <a href="./many-images.html">gallery</a>. Firefox and Safari open one file at a time.</p></div><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">the viewer</a>, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of LSM files</strong>, in Chrome and Edge. One file opens. Several show a list with a picture of each, and files one folder down are listed too. After you pick one, a gallery of pictures under the image takes you to the next. See <a href="./many-images.html">Folders, Zips and Series</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>, or a Zenodo file link that ends in <code>/content</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Channels</strong> with the names and colours ZEN gave them, such as <code>ChS1-T1</code>.</li><li><strong>Spectral (lambda) scans</strong> as one channel per wavelength band, each in the colour of its wavelength.</li><li><strong>Z and time.</strong> Sliders step through the planes. A Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>8 and 16-bit data</strong>, uncompressed, as LSM confocals save it.</li><li><strong>Pixel size, Z step and time interval</strong> from the file. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>An LSM re-saved by Fiji or another tool has lost the Zeiss metadata. It opens as a TIFF, with the channels, sizes and pixel size the file itself states. See <a href="./tiff.html">TIFF and ImageJ Files</a>.</p><p>An LSM stores one resolution. The viewer makes the lower resolutions itself, so a large image zooms out and opens in 3D.</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>A line, point or x-z scan</td><td>This LSM is a line, point or x-z scan, which the viewer does not show yet.</td></tr><tr><td>Tiles or positions that were never stitched</td><td>This LSM holds unstitched tiles or positions. Open a stitched copy, or convert it to OME-Zarr.</td></tr><tr><td>One plane of all channels over 256 MB</td><td>too large to open without a pyramid. Convert it to OME-Zarr to open it here.</td></tr><tr><td>A file of 4 GB or more</td><td>LSM files of 4 GB or more cannot be read yet. Convert it to OME-Zarr to open it here.</td></tr><tr><td>A compressed file, such as LZW</td><td>This LSM uses a compression the viewer cannot read yet.</td></tr><tr><td>Another pixel type</td><td>This LSM has a pixel type the viewer cannot read yet.</td></tr></tbody></table><p><a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert to OME-Zarr</a> to open a very large image with every resolution.</p><h2 id="public-lsm-files-to-try" tabindex="-1">Public LSM Files to Try <a class="header-anchor" href="#public-lsm-files-to-try" aria-label="Permalink to &quot;Public LSM Files to Try&quot;">​</a></h2><ul><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F14510432%2Ffiles%2F10-01.lsm%2Fcontent" target="_blank" rel="noreferrer">10-01.lsm</a>: four channels, 16-bit. Salama Lab, Fred Hutchinson Cancer Center, <a href="https://zenodo.org/records/14510432" target="_blank" rel="noreferrer">Zenodo 14510432</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F13286257%2Ffiles%2Fsofa%2520eye_zebrafish_spectral%2520and%2520zstack_01.lsm%2Fcontent" target="_blank" rel="noreferrer">A spectral Z-stack of a zebrafish eye</a>: 25 wavelength bands, 44 planes. Bruno Schuty and Paola Lepanto, <a href="https://zenodo.org/records/13286257" target="_blank" rel="noreferrer">Zenodo 13286257</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F33141%2Ffiles%2FGMRFlp_CD4tdGFP_GMR-myr-RFP_P28_culture_fast1_1-31-13.lsm%2Fcontent" target="_blank" rel="noreferrer">A time-lapse of growth cones</a>: 60 time points of 30 planes. Özel, Langen, Hassan and Hiesinger, <a href="https://zenodo.org/records/33141" target="_blank" rel="noreferrer">Zenodo 33141</a>, CC0.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>10-01.lsm</code>, Salama Lab, Fred Hutchinson Cancer Center, <a href="https://zenodo.org/records/14510432" target="_blank" rel="noreferrer">Zenodo 14510432</a>, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;Zeiss LSM file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',20))])}const y=o(c,[["render",p]]);export{S as __pageData,y as default};
